const guest = $('Fetch Guest').first().json;
const guestRow = Array.isArray(guest) ? guest[0] : guest;
const braveBody = $('Brave Person').first().json;
const braveResults = ((braveBody && braveBody.web && braveBody.web.results) || []).slice(0, 4).map(r => ({
  title: r.title, url: r.url, description: r.description
}));
const ventures = $('Fetch Ventures').first().json;
const ventureList = Array.isArray(ventures) ? ventures : [];
const venture = ventureList.find(v => v.slug === guestRow.podcast_target) || null;
const exaBody = $('Exa Enrich').first().json;
const exa = ((exaBody && exaBody.results) || []).slice(0, 4).map(r => ({ title: r.title, url: r.url, text: (r.text || '').slice(0, 350) }));
return [{ json: { guest: guestRow, venture, brave: braveResults, exa } }];

const item = $input.first();
const blocks = item.json.content || [];
const text = blocks.map(b => b.text || '').join('\n').trim();
let parsed = null;
try {
  const a = text.indexOf('{');
  const b = text.lastIndexOf('}');
  if (a >= 0 && b > a) parsed = JSON.parse(text.slice(a, b + 1));
} catch (e) { parsed = null; }
if (!parsed || !parsed.pitch_draft) {
  return [{ json: { id: $('Compile Context').first().json.guest.id, pitch_draft: null, best_channel: null, quality_score: 'red', error: 'parse_failed' } }];
}
const draft = String(parsed.pitch_draft || '').trim();
const hasEmDash = draft.includes('—');
const hasEnDash = draft.includes('–');
const tooLong = draft.split(/\s+/).length > 130;
const tooShort = draft.split(/\s+/).length < 60;
let quality = 'green';
const flags = [];
if (hasEmDash || hasEnDash) { quality = 'red'; flags.push('dash_violation'); }
if (tooLong) { if (quality === 'green') quality = 'amber'; flags.push('over_length'); }
if (tooShort) { if (quality === 'green') quality = 'amber'; flags.push('under_length'); }
const allowedChannels = new Set(['email', 'linkedin', 'twitter', 'personal_url']);
const channel = allowedChannels.has(parsed.best_channel) ? parsed.best_channel : null;
return [{ json: {
  id: $('Compile Context').first().json.guest.id,
  pitch_draft: draft,
  best_channel: channel,
  quality_score: quality,
  flags
} }];
